import fs from 'node:fs';
import path from 'node:path';

function walk(dir) {
  let results = [];
  const list = fs.readdirSync(dir);
  for (const file of list) {
    const full = path.join(dir, file);
    const stat = fs.statSync(full);
    if (stat.isDirectory()) {
      results = results.concat(walk(full));
    } else if (file.endsWith('.html') || file.endsWith('.css') || file.endsWith('.js')) {
      results.push(full);
    }
  }
  return results;
}

const files = walk('src');
const referenced = new Set();
for (const file of files) {
  const content = fs.readFileSync(file, 'utf8');
  const matches = content.match(/(?:\/assets\/|\/channels\/|\/logos\/|\/tweets\/)[a-zA-Z0-9_\-\.\/]+/g) || [];
  for (let m of matches) {
    const clean = m.replace(/["'`\);,\s].*$/, '');
    if (/\.(js|css|webp|png|svg|woff2|jpeg|jpg)$/.test(clean)) {
      referenced.add(clean);
    }
  }
}

console.log('Total referenced assets found:', referenced.size);
const missing = [];
for (const ref of referenced) {
  const local = path.join('src', ref.startsWith('/') ? ref.slice(1) : ref);
  if (!fs.existsSync(local)) {
    missing.push(ref);
  }
}
console.log('Missing assets count:', missing.length);
for (const m of missing) {
  console.log('Missing:', m);
}

// Download missing
async function run() {
  for (const m of missing) {
    try {
      const res = await fetch('https://www.boardy.ai' + m);
      if (res.ok) {
        const dest = path.join('src', m.startsWith('/') ? m.slice(1) : m);
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.writeFileSync(dest, Buffer.from(await res.arrayBuffer()));
        console.log('Successfully fetched:', m);
      } else {
        console.log('Not on remote (status ' + res.status + '):', m);
      }
    } catch (e) {
      console.log('Error fetching ' + m + ':', e.message);
    }
  }
}
run();

