import fs from 'node:fs';
import path from 'node:path';

const files = ['index.raw.html', 'events.raw.html', 'booking.raw.html', 'chatgpt.raw.html', 'articles.raw.html'];
const rootAssets = new Set();
for (const f of files) {
  const content = fs.readFileSync('src/' + f, 'utf8');
  const matches = content.match(/(?:src|href)=["']\/([^"'\s>]+)["']/g) || [];
  for (const m of matches) {
    const asset = m.replace(/^(?:src|href)=["']\//, '').replace(/["']$/, '');
    if (!asset.startsWith('assets/') && !asset.startsWith('channels/') && !asset.startsWith('logos/') && !asset.startsWith('tweets/') && !asset.startsWith('articles') && !asset.startsWith('events') && !asset.startsWith('booking') && !asset.startsWith('chatgpt') && !asset.startsWith('http') && asset.includes('.')) {
      rootAssets.add(asset);
    }
  }
}
console.log('Root assets referenced in HTML:', Array.from(rootAssets));
for (const a of rootAssets) {
  const local = path.join('src', a);
  const exists = fs.existsSync(local);
  console.log(a, 'exists in src:', exists);
  if (!exists) {
    try {
      const res = await fetch('https://www.boardy.ai/' + a);
      if (res.ok) {
        fs.mkdirSync(path.dirname(local), { recursive: true });
        fs.writeFileSync(local, Buffer.from(await res.arrayBuffer()));
        console.log('Fetched', a);
      } else {
        console.log('Failed fetch', a, res.status);
      }
    } catch (e) {
      console.log('Err', a, e.message);
    }
  }
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const srcDir = path.join(__dirname, 'src');
const distDir = path.join(__dirname, 'dist');

console.log('Building Boardy static site...');

// 1. Clean dist folder
if (fs.existsSync(distDir)) {
  fs.rmSync(distDir, { recursive: true, force: true });
}
fs.mkdirSync(distDir, { recursive: true });

// 2. Helper to copy directories recursively
function copyDir(src, dest) {
  if (!fs.existsSync(src)) return;
  fs.mkdirSync(dest, { recursive: true });
  const entries = fs.readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDir(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

// 3. Copy asset directories
const assetDirs = ['assets', 'channels', 'logos', 'tweets', 'videos'];
for (const dir of assetDirs) {
  const s = path.join(srcDir, dir);
  const d = path.join(distDir, dir);
  if (fs.existsSync(s)) {
    copyDir(s, d);
    console.log(`Copied ${dir}/`);
  }
}

// Copy root static files (.webp, .png, .jpg, .jpeg, .svg, .ico, .mp4, .md)
const rootFiles = fs.readdirSync(srcDir);
for (const file of rootFiles) {
  const fullPath = path.join(srcDir, file);
  const stat = fs.statSync(fullPath);
  if (stat.isFile() && !file.endsWith('.html')) {
    fs.copyFileSync(fullPath, path.join(distDir, file));
  }
}

// Helper to prepare HTML with API mock injected
function prepareHtml(rawHtml) {
  let html = rawHtml;
  // Ensure lang is set
  if (!html.includes('<html lang="en"')) {
    html = html.replace(/<html[^>]*>/i, '<html lang="en">');
  }
  // Inject api-mock.js right after <head>
  if (!html.includes('/assets/api-mock.js')) {
    html = html.replace('<head>', '<head>\n    <script src="/assets/api-mock.js"></script>');
  }
  return html;
}

// 4. Build index.html
if (fs.existsSync(path.join(srcDir, 'index.raw.html'))) {
  const raw = fs.readFileSync(path.join(srcDir, 'index.raw.html'), 'utf8');
  fs.writeFileSync(path.join(distDir, 'index.html'), prepareHtml(raw));
  console.log('Built dist/index.html');
}

// 5. Build /events
if (fs.existsSync(path.join(srcDir, 'events.raw.html'))) {
  const eventsDir = path.join(distDir, 'events');
  fs.mkdirSync(eventsDir, { recursive: true });
  const raw = fs.readFileSync(path.join(srcDir, 'events.raw.html'), 'utf8');
  fs.writeFileSync(path.join(eventsDir, 'index.html'), prepareHtml(raw));
  console.log('Built dist/events/index.html');
}

// 6. Build /booking
if (fs.existsSync(path.join(srcDir, 'booking.raw.html'))) {
  const bookingDir = path.join(distDir, 'booking');
  fs.mkdirSync(bookingDir, { recursive: true });
  const raw = fs.readFileSync(path.join(srcDir, 'booking.raw.html'), 'utf8');
  fs.writeFileSync(path.join(bookingDir, 'index.html'), prepareHtml(raw));
  console.log('Built dist/booking/index.html');
}

// 7. Build /chatgpt
if (fs.existsSync(path.join(srcDir, 'chatgpt.raw.html'))) {
  const chatgptDir = path.join(distDir, 'chatgpt');
  fs.mkdirSync(chatgptDir, { recursive: true });
  const raw = fs.readFileSync(path.join(srcDir, 'chatgpt.raw.html'), 'utf8');
  fs.writeFileSync(path.join(chatgptDir, 'index.html'), prepareHtml(raw));
  console.log('Built dist/chatgpt/index.html');
}

// 8. Build /articles (keep existing 100% compliant articles build)
const articlesSrcDir = path.join(srcDir, 'articles');
const articlesDistDir = path.join(distDir, 'articles');
if (fs.existsSync(articlesSrcDir)) {
  copyDir(articlesSrcDir, articlesDistDir);
  console.log('Copied articles/ static files');
}

if (fs.existsSync(path.join(srcDir, 'articles.raw.html'))) {
  fs.mkdirSync(articlesDistDir, { recursive: true });
  let articlesHtml = fs.readFileSync(path.join(srcDir, 'articles.raw.html'), 'utf8');
  if (!articlesHtml.includes('<html lang="en"')) {
    articlesHtml = articlesHtml.replace(/<html[^>]*>/i, '<html lang="en">');
  }
  fs.writeFileSync(path.join(articlesDistDir, 'index.html'), articlesHtml);
  console.log('Built dist/articles/index.html');
}

console.log('Build complete! All files generated in app/dist/');

